  .frame {
    min-height: 100dvh;
    margin-inline: clamp(16px, 3vw, 56px);
    border-inline: 2px solid var(--color-divider);
    display: flex;
    flex-direction: column;
  }
  @media (max-width: 660px) {
    .frame {
      margin-inline: 0;
      border-inline: 0;
    }
  }
</style>
