import { describe, expect, it } from 'vitest';

import { CashbackApiError } from '../cashback/api';
import type { Session } from '../editorial/session';
import { isUnauthorized, needsSignIn } from './gate';

function session(authenticated: boolean): Session {
  return {
    displayName: authenticated ? 'A Member' : '',
    email: authenticated ? 'member@example.invalid' : '',
    role: 'reader',
    token: authenticated ? 'a-token' : null,
    authenticated,
  };
}

describe('needsSignIn', () => {
  it('sends a signed-out visitor to sign in when there is a real api', () => {
    expect(needsSignIn(session(false), 'api')).toBe(true);
  });

  it('lets a signed-in member through', () => {
    expect(needsSignIn(session(true), 'api')).toBe(false);
  });

  it.each([true, false])(
    'never redirects in fixture mode, signed in %s',
    (authenticated) => {
      // A pull-request preview has no api and nobody signed in, and its whole
      // job is to render the screens for review. Redirecting there would make
      // previews useless for the one thing they exist for.
      expect(needsSignIn(session(authenticated), 'fixture')).toBe(false);
    },
  );
});

describe('isUnauthorized', () => {
  it.each([401, 403])('recognises %d as the api declining the caller', (status) => {
    // 401 is no token or one that does not verify; 403 is a token that
    // verifies for somebody this route is not for. Neither is a state a
    // member can wait out, and signing in cures both.
    expect(isUnauthorized(new CashbackApiError('refused', status, null))).toBe(true);
  });

  it.each([404, 409, 429, 500, 502, 503])(
    'leaves %d alone, because signing in again would not help',
    (status) => {
      expect(isUnauthorized(new CashbackApiError('answered', status, null))).toBe(false);
    },
  );

  it.each([
    ['a plain error', new Error('boom')],
    ['a string', 'boom'],
    ['null', null],
    ['undefined', undefined],
  ])('is false for %s, which carries no status at all', (_label, thrown) => {
    expect(isUnauthorized(thrown)).toBe(false);
  });
});

