import type { APIRoute } from 'astro';
import { API_BASE_URL, APP_ENV, PUBLIC_APP_VERSION } from 'astro:env/server';

import {
  CashbackApiError,
  CashbackConfigurationError,
  createCashbackApi,
} from '../../../lib/cashback/api';
import { isSameOrigin } from '../../../lib/csrf';
import { sessionOf } from '../../../lib/editorial/session';
import { safeReturnPath } from '../../../lib/member/access';

/**
 * The click-out: the one place a member leaves for a shop.
 *
 * It is a POST rather than a link because it creates a row. `POST
 * /clickouts` commits the click and its rate snapshot **before** it answers,
 * so a member who arrives at the shop is a member whose click exists; a
 * GET that a prefetcher or a crawler could follow would manufacture clicks
 * nobody made, and every one of them would be evidence in a later
 * attribution.
 *
 * The redirect is a 303 to the target the API returned, and only to that:
 * the offer id names the deeplink, the member never supplies a URL, and so
 * there is no open redirect on the way OUT.
 *
 * There was one on the way BACK. This docstring reasoned carefully about the
 * success path and left the failure path taking a `back` field off the form
 * and checking it with `back.startsWith('/')` — which `//evil.example`
 * passes, being protocol-relative and off this site. `safeReturnPath`
 * (#564) is the check that was already written for this, and refuses that,
 * `/\host`, control characters and anything absurdly long.
 *
 * A failure renders as a refusal on the merchant page rather than sending
 * the member onward untracked, because an untracked purchase earns nothing
 * and looks exactly like a tracked one until the cashback fails to appear.
 */
export const POST: APIRoute = async ({ request, redirect, url }) => {
  if (!isSameOrigin(request, url.origin)) {
    return new Response('cross-origin click-out refused', { status: 403 });
  }

  const form = await request.formData();
  const offerId = form.get('offer_id');
  const back = form.get('back');
  if (typeof offerId !== 'string' || offerId === '') {
    return new Response('offer_id is required', { status: 400 });
  }

  /**
   * Where a refusal sends them, with the outcome attached.
   *
   * Built through `URL` rather than by concatenating a `?`: `back` carries no
   * query today, and the day it does, string-joining produces
   * `…?a=1?clickout=409` — a second `?` that every parser reads as part of
   * the first parameter's value.
   */
  const backTo = (status: number): string => {
    const target = new URL(
      safeReturnPath(typeof back === 'string' ? back : null, '/'),
      url.origin,
    );
    target.searchParams.set('clickout', String(status));
    return `${target.pathname}${target.search}`;
  };

  try {
    // Inside the try, because it throws. A deployment with APP_ENV=prod and
    // no API_BASE_URL threw CashbackConfigurationError straight out of this
    // route: an Astro error page to somebody who had just pressed "open the
    // shop", instead of a refusal on the page they came from.
    const session = sessionOf(request);
    const api = createCashbackApi(API_BASE_URL, {
      appEnv: APP_ENV,
      token: session.token,
      appVersion: PUBLIC_APP_VERSION,
    });
    const { redirect_url } = await api.clickout(offerId);
    return redirect(redirect_url, 303);
  } catch (error) {
    // A misconfigured deployment is otherwise silent: the member sees the
    // same refusal as a network fault and only an operator can tell them
    // apart, so the operator gets told.
    if (error instanceof CashbackConfigurationError) {
      console.error(`cashback: ${error.message}`);
    }
    // 403 (not opted in), 409 (expired offer or inactive merchant), 429 and
    // 401 are all outcomes the member has to be told about, and none of them
    // is a reason to send them to the shop anyway. The merchant page turns
    // the status into a sentence; anything that is not the api refusing is a
    // 502, which is what "we could not reach the shop" means here.
    const status = error instanceof CashbackApiError ? error.status : 502;
    return redirect(backTo(status), 303);
  }
};

import { describe, expect, it, vi } from 'vitest';

/**
 * The click-out endpoint (issue #596).
 *
 * It had no test at all, which is how an open redirect sat on its failure
 * path under a docstring explaining why it had none. The route is an
 * `APIRoute`, so its `POST` is called directly — no container, no rendering.
 *
 * With no `API_BASE_URL` the client answers from fixtures, whose `clickout`
 * resolves; the refusal cases therefore drive the failure path by making the
 * api throw rather than by hoping one does.
 */

const ORIGIN = 'https://example.invalid';
const OFFER = '0be7b5b7-eccd-4507-ab69-8a44d0a404e8';

/** A `redirect` with Astro's signature, recording where it was sent. */
function harness(): {
  redirect: (location: string, status?: number) => Response;
  sent: string[];
} {
  const sent: string[] = [];
  return {
    redirect: (location: string, status = 302): Response => {
      sent.push(location);
      return new Response(null, { status, headers: { Location: location } });
    },
    sent,
  };
}

async function post(
  body: Record<string, string>,
  options: { origin?: string | null; env?: Record<string, unknown> } = {},
): Promise<{ response: Response; sent: string[] }> {
  vi.resetModules();
  vi.doMock('astro:env/server', () => options.env ?? { APP_ENV: 'dev', API_BASE_URL: undefined, PUBLIC_APP_VERSION: undefined });
  const { POST } = await import('./clickout');

  const form = new FormData();
  for (const [key, value] of Object.entries(body)) {
    form.set(key, value);
  }
  const headers = new Headers();
  const origin = options.origin === undefined ? ORIGIN : options.origin;
  if (origin !== null) {
    headers.set('origin', origin);
  }
  const url = new URL(`${ORIGIN}/api/cashback/clickout`);
  const { redirect, sent } = harness();
  const response = await POST({
    request: new Request(url, { method: 'POST', body: form, headers }),
    redirect,
    url,
  } as unknown as Parameters<typeof POST>[0]);

  return { response: response as Response, sent };
}

describe('the click-out endpoint', () => {
  it('refuses a cross-origin post', async () => {
    // A click is a row with money behind it, and `isSameOrigin` compares
    // hosts rather than whole origins for the reason csrf.ts sets out.
    const { response } = await post({ offer_id: OFFER }, { origin: 'https://evil.invalid' });

    expect(response.status).toBe(403);
  });

  it('refuses a post carrying no origin or referer at all', async () => {
    const { response } = await post({ offer_id: OFFER }, { origin: null });

    expect(response.status).toBe(403);
  });

  it('refuses a post with no offer', async () => {
    const { response } = await post({ back: '/el/munich/cashback/agora' });

    expect(response.status).toBe(400);
  });

  it('forwards exactly the target the api named, and attaches nothing', async () => {
    const { response, sent } = await post({ offer_id: OFFER });

    expect(response.status).toBe(303);
    expect(sent).toHaveLength(1);
    // The fixture answers `/` on purpose — a preview must never send anybody
    // to a real shop under a click that was never recorded. What this pins
    // is that a SUCCESS forwards the api's target untouched: no outcome
    // parameter, no rewriting, nothing of ours added to a deeplink whose
    // query string is what the network attributes the sale by.
    expect(sent[0]).toBe('/');
    expect(sent[0]).not.toContain('clickout=');
  });

  /*
   * The failure path, and the reason this file exists.
   */

  it.each([
    ['//evil.example', 'protocol-relative, and off this site'],
    ['//evil.example/el/munich', 'the same with a plausible tail'],
    ['https://evil.example/', 'an absolute URL'],
    ['/\\evil.example', 'a backslash a browser normalises to a slash'],
    ['el/munich', 'relative, so it depends on where it is read'],
    ['/auth/confirm', 'back into the sign-in flow'],
  ])('never sends a refusal to %s (%s)', async (back) => {
    const { sent } = await post(
      { offer_id: 'not-a-uuid-so-the-api-refuses', back },
      { env: { APP_ENV: 'prod', API_BASE_URL: '', PUBLIC_APP_VERSION: undefined } },
    );

    expect(sent).toHaveLength(1);
    expect(sent[0]).toBe('/?clickout=502');
    expect(sent[0]).not.toContain('evil.example');
  });

  it('keeps a return path that is genuinely this site’s', async () => {
    const { sent } = await post(
      { offer_id: 'not-a-uuid-so-the-api-refuses', back: '/el/munich/cashback/agora' },
      { env: { APP_ENV: 'prod', API_BASE_URL: '', PUBLIC_APP_VERSION: undefined } },
    );

    expect(sent[0]).toBe('/el/munich/cashback/agora?clickout=502');
  });

  it('adds its outcome to a return path that already carries a query', async () => {
    // `?` used to be appended unconditionally, which built `…?a=1?clickout=x`
    // the moment `back` carried anything.
    const { sent } = await post(
      { offer_id: 'not-a-uuid-so-the-api-refuses', back: '/el/munich/cashback?q=agora' },
      { env: { APP_ENV: 'prod', API_BASE_URL: '', PUBLIC_APP_VERSION: undefined } },
    );

    expect(sent[0]).toBe('/el/munich/cashback?q=agora&clickout=502');
    expect(sent[0]).not.toContain('?q=agora?');
  });

  it('redirects rather than throwing when the deployment names no api', async () => {
    /*
     * APP_ENV=prod with no API_BASE_URL makes createCashbackApi throw. It
     * used to do so from outside the try, so somebody who had just pressed
     * "open the shop" got an Astro error page instead of a refusal on the
     * page they came from.
     */
    const { response, sent } = await post(
      { offer_id: OFFER, back: '/el/munich/cashback/agora' },
      { env: { APP_ENV: 'prod', API_BASE_URL: '', PUBLIC_APP_VERSION: undefined } },
    );

    expect(response.status).toBe(303);
    expect(sent[0]).toBe('/el/munich/cashback/agora?clickout=502');
  });
});

import { experimental_AstroContainer as AstroContainer } from 'astro/container';
import { describe, expect, it } from 'vitest';

import { cashbackStrings } from '../../../../i18n/cashback';
import { TERMS_TEXT_VERSION } from '../../../../lib/legal/terms';
import { READING_LANGUAGES } from '../../../../lib/reader/axes';
import Join from './join.astro';

/**
 * The opt-in screen, rendered (issue #592).
 *
 * With no `API_BASE_URL` the client answers from fixtures, which report every
 * member as already participating — so without the fixture-mode branch this
 * page would render its "nothing to do" state and nothing else, on every
 * preview and every development run. That branch is what these cases mostly
 * exercise, and it is the state a reviewer sees.
 */

const RENDER_TIMEOUT_MS = 20_000;

async function render(path: string): Promise<string> {
  const container = await AstroContainer.create();
  const url = new URL(path, 'https://example.invalid');
  const [, lang, place] = url.pathname.split('/');
  return container.renderToString(Join, {
    request: new Request(url),
    params: { lang: lang ?? '', place: place ?? '' },
  });
}

describe.each(READING_LANGUAGES)('the opt-in in %s', (lang) => {
  it(
    'asks for the consent, and names the version being accepted',
    async () => {
      const html = await render(`/${lang}/munich/cashback/join`);
      const t = cashbackStrings(lang);

      expect(html).toContain(t.joinHeading);
      expect(html).toContain(t.optIn);
      // The fixture brand's version, which is what this render is against.
      expect(html).toMatch(/Με τη συμμετοχή αποδέχεσαι|Mit der Teilnahme nimmst du/);
    },
    RENDER_TIMEOUT_MS,
  );

  it(
    'links the terms it is asking somebody to accept',
    async () => {
      // Accepting a version whose text is one click away is the least this
      // screen owes: the whole reason /{lang}/terms exists.
      const html = await render(`/${lang}/munich/cashback/join`);

      expect(html).toContain(cashbackStrings(lang).readTerms);
      expect(html).toContain(`href="/${lang}/terms"`);
    },
    RENDER_TIMEOUT_MS,
  );

  it(
    'posts to itself, and only same-origin',
    async () => {
      const html = await render(`/${lang}/munich/cashback/join`);

      expect(html).toContain('<form');
      expect(html).toMatch(/method="post"/i);
      expect(html).toContain(`action="/${lang}/munich/cashback/join"`);
    },
    RENDER_TIMEOUT_MS,
  );

  it(
    'refuses a cross-origin post rather than recording a consent',
    async () => {
      // A consent is a record with money behind it. `isSameOrigin` compares
      // hosts and refuses a request carrying neither Origin nor Referer.
      const container = await AstroContainer.create();
      const url = new URL(`https://example.invalid/${lang}/munich/cashback/join`);
      const response = await container.renderToResponse(Join, {
        request: new Request(url, {
          method: 'POST',
          headers: { origin: 'https://evil.invalid' },
        }),
        params: { lang, place: 'munich' },
      });

      expect(response.status).toBe(403);
    },
    RENDER_TIMEOUT_MS,
  );

  it(
    'carries the reader’s two axes into every link it offers',
    async () => {
      // Language and place travel separately and neither is chosen on the
      // reader's behalf (Principle VII, FR-009).
      const html = await render(`/${lang}/munich+greece/cashback/join`);

      expect(html).toContain(`href="/${lang}/munich+greece/cashback"`);
      expect(html).not.toContain('/el/munich/cashback/join');
    },
    RENDER_TIMEOUT_MS,
  );

  it(
    'leaks no value it never had',
    async () => {
      const html = await render(`/${lang}/munich/cashback/join`);

      for (const leak of ['undefined', 'NaN', '[object Object]', 'href=""']) {
        expect(html, `rendered ${leak}`).not.toContain(leak);
      }
    },
    RENDER_TIMEOUT_MS,
  );

  it(
    'never posts the string "undefined" as somebody’s recorded consent',
    async () => {
      // `documents` is a map. A brand without a terms document must offer no
      // button at all rather than send the api a version that is not one.
      const html = await render(`/${lang}/munich/cashback/join`);

      expect(html).not.toContain('undefined');
      expect(TERMS_TEXT_VERSION).not.toBe('undefined');
    },
    RENDER_TIMEOUT_MS,
  );
});

describe('a language this application does not serve', () => {
  it(
    'is rewritten to the not-found page rather than rendered',
    async () => {
      await expect(render('/fr/munich/cashback/join')).rejects.toThrow(/route \/404/);
    },
    RENDER_TIMEOUT_MS,
  );
});

describe('a place this application does not serve', () => {
  it(
    'is rewritten too, rather than rendering an opt-in for nowhere',
    async () => {
      await expect(render('/el/atlantis/cashback/join')).rejects.toThrow(/route \/404/);
    },
    RENDER_TIMEOUT_MS,
  );
});

