    color: var(--ink-muted);
    text-wrap: pretty;
  }

  .band {
    margin: var(--space-6) 0 0;
    padding: var(--space-3) var(--space-4);
    border-left: 2px solid var(--color-accent-700);
    background: var(--color-accent-100);
    max-width: 56ch;
    font-size: 13px;
    line-height: 1.55;
    color: var(--color-accent-800);
    text-wrap: pretty;
  }

  /* The offer and the done state share a measure, so the page does not
     jump between them. */
  .offer,
  .done {
    margin-top: var(--space-6);
    max-width: 46ch;
  }

  .done p {
    margin: 0 0 var(--space-3);
    font-size: 14px;
