    max-width: 56ch;
    font-size: 13px;
    line-height: 1.55;
    color: var(--color-accent-800);
    text-wrap: pretty;
  }

  /* Two panes on desktop, stacked on a phone — the boards' own split. */
  .cols {
    display: grid;
    gap: var(--space-6);
    margin-top: var(--space-6);
  }

  @media (min-width: 800px) {
    .cols {
      grid-template-columns: 1fr 1fr;
      gap: var(--space-8);
    }
  }

  .pane h2,
  .activity h2 {
    margin: 0 0 var(--space-3);
    font-family: var(--font-heading);
    font-weight: var(--font-heading-weight);
    font-size: 12px;
    letter-spacing: 0.08em;
    text-transform: uppercase;
    color: var(--ink-muted);
  }

  .row {
    display: flex;
    gap: var(--space-4);
    align-items: baseline;
