import io
p = 'profile.astro'
s = io.open(p, encoding='utf-8').read()

old = """  /* Two panes on desktop, stacked on a phone — the boards' own split. */
  .cols {
    display: grid;
    gap: var(--space-6);
    margin-top: var(--space-6);
  }

  @media (min-width: 800px) {
    .cols {
      grid-template-columns: 1fr 1fr;
      gap: var(--space-8);
    }
  }
"""
new = """  /* Two panes on desktop, stacked on a phone — the boards' own split.
     Written widest-first, because every other breakpoint in this
     application is a max-width and a lone min-width leaves the reader of
     this file guessing which way the cascade runs. */
  .cols {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: var(--space-8);
    margin-top: var(--space-6);
  }

  @media (max-width: 900px) {
    .cols {
      grid-template-columns: 1fr;
      gap: var(--space-6);
    }
  }
"""
assert old in s
s = s.replace(old, new, 1)

old_v = """  .v {
    text-align: right;
    color: var(--color-text);
    overflow-wrap: anywhere;
  }
"""
new_v = """  .v {
    text-align: right;
    color: var(--color-text);
    overflow-wrap: anywhere;
  }

  /* On a phone the label and its value stop sharing a line.
     `Ηλεκτρονικό ταχυδρομείο` beside `member@example.test` in 390px left
     the two fighting over the width: the label wrapped to two lines and
     `overflow-wrap` broke the address wherever it happened to land,
     orphaning a single letter. Stacking gives the address the full
     measure, so it never has to be broken at all. 660px is this
     application's phone breakpoint — ReaderLayout drops its frame there. */
  @media (max-width: 660px) {
    .page {
      padding: var(--space-5) var(--space-4) var(--space-7);
    }

    .row {
      display: block;
      padding: var(--space-2) 0 var(--space-3);
    }

    .v {
      display: block;
      margin-top: 2px;
      text-align: left;
    }

    .chip,
    .tag {
      margin-left: 0;
    }
  }
"""
assert old_v in s
s = s.replace(old_v, new_v, 1)
io.open(p, 'w', encoding='utf-8', newline='\n').write(s)
print('patched')
PY
