const out = [...document.querySelectorAll('iframe')].map((f, i) => {
  const d = f.contentDocument, w = f.contentWindow;
  const page = d.querySelector('main.page');
  const cs = page ? getComputedStyle(page) : null;
  const cols = d.querySelector('.cols');
  const row = d.querySelector('.row');
  // widest element that sticks out past the document
  const over = [...d.querySelectorAll('*')]
    .map(e => ({ t: e.tagName + '.' + (e.className || ''), r: e.getBoundingClientRect().right }))
    .filter(x => x.r > d.documentElement.clientWidth + 1)
    .sort((a, b) => b.r - a.r).slice(0, 3);
  return {
    frame: i === 0 ? 'el' : 'de',
    innerWidth: w.innerWidth,
    clientWidth: d.documentElement.clientWidth,
    scrollWidth: d.documentElement.scrollWidth,
    overflowsX: d.documentElement.scrollWidth > d.documentElement.clientWidth + 1,
    pagePaddingLeft: cs && cs.paddingLeft,
    pagePaddingRight: cs && cs.paddingRight,
    colsTemplate: cols && getComputedStyle(cols).gridTemplateColumns,
    rowDisplay: row && getComputedStyle(row).display,
    offenders: over,
  };
});
JSON.stringify(out, null, 1);

